/* com.portal.board.bbs.BBSAttributeManageMapper.deleteBBSMasterInf */
UPDATE LETTNBBSMASTER
   SET USE_AT          = 'N',
       LAST_UPDUSR_ID  = #{lastUpdusrId},
       LAST_UPDT_PNTTM = SYSDATE()
 WHERE BBS_ID = #{bbsId}

