/* com.portal.board.bbs.BBSAttributeManageMapper.selectBdMstrListByTrget */ SELECT a.BBS_ID, a.BBS_TY_CODE, b.CODE_NM AS BBS_TY_CODE_NM, a.BBS_ATTRB_CODE, c.CODE_NM AS BBS_ATTRB_CODE_NM, a.BBS_NM, a.TMPLAT_ID, a.USE_AT, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM FROM LETTNBBSMASTER a INNER JOIN LETTNBBSUSE d ON a.BBS_ID = d.BBS_ID LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM004' AND USE_AT = 'Y') b ON a.BBS_TY_CODE = b.CODE LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM009' AND USE_AT = 'Y') c ON a.BBS_ATTRB_CODE = c.CODE WHERE d.TRGET_ID = #{trgetId}
AND a.BBS_NM LIKE CONCAT('%', #{searchWrd}, '%')
AND b.CODE_NM LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.board.bbs.BBSAttributeManageMapper.selectBdMstrListCntByTrget */ SELECT COUNT(a.BBS_ID) FROM LETTNBBSMASTER a INNER JOIN LETTNBBSUSE d ON a.BBS_ID = d.BBS_ID LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM004' AND USE_AT = 'Y') b ON a.BBS_TY_CODE = b.CODE LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM009' AND USE_AT = 'Y') c ON a.BBS_ATTRB_CODE = c.CODE WHERE d.TRGET_ID = #{trgetId}
AND a.BBS_NM LIKE CONCAT('%', #{searchWrd}, '%')
AND b.CODE_NM LIKE CONCAT('%', #{searchWrd}, '%')

/* com.portal.board.bbs.BBSAttributeManageMapper.selectNotUsedBdMstrList */ SELECT a.BBS_ID, a.BBS_TY_CODE, b.CODE_NM AS BBS_TY_CODE_NM, a.BBS_ATTRB_CODE, c.CODE_NM AS BBS_ATTRB_CODE_NM, a.BBS_NM, a.TMPLAT_ID, a.USE_AT, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM FROM LETTNBBSMASTER a LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM004' AND USE_AT = 'Y') b ON a.BBS_TY_CODE = b.CODE LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM009' AND USE_AT = 'Y') c ON a.BBS_ATTRB_CODE = c.CODE WHERE a.USE_AT = 'Y' AND a.BBS_ID NOT IN (SELECT BBS_ID FROM LETTNBBSUSE WHERE USE_AT = 'Y')
AND a.BBS_NM LIKE CONCAT('%', #{searchWrd}, '%')
AND b.CODE_NM LIKE CONCAT('%', #{searchWrd}, '%')
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.board.bbs.BBSAttributeManageMapper.selectNotUsedBdMstrListCnt */ SELECT COUNT(a.BBS_ID) FROM LETTNBBSMASTER a LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM004' AND USE_AT = 'Y') b ON a.BBS_TY_CODE = b.CODE LEFT OUTER JOIN (SELECT CODE_ID, CODE, CODE_NM FROM LETTCCMMNDETAILCODE WHERE CODE_ID = 'COM009' AND USE_AT = 'Y') c ON a.BBS_ATTRB_CODE = c.CODE WHERE a.USE_AT = 'Y' AND a.BBS_ID NOT IN (SELECT BBS_ID FROM LETTNBBSUSE WHERE USE_AT = 'Y')
AND a.BBS_NM LIKE CONCAT('%', #{searchWrd}, '%')
AND b.CODE_NM LIKE CONCAT('%', #{searchWrd}, '%')
